private val CURRENCIES = listOf("YER", "SAR", "USD")
private val LABELS = mapOf("YER" to "ريال يمني", "SAR" to "ريال سعودي", "USD" to "دولار")
private fun money(v: Long) = BigDecimal(v).movePointLeft(2).stripTrailingZeros().toPlainString()
private fun parseMinor(v: String): Long? = runCatching { BigDecimal(v.trim()).setScale(2, RoundingMode.UNNECESSARY).movePointRight(2).longValueExact() }.getOrNull()
private fun signed(v: Long) = when { v > 0 -> "عليه ${money(v)}"; v < 0 -> "له ${money(-v)}"; else -> "متوازن 0" }
private fun dateLabel(v: Long) = SimpleDateFormat("dd-MM-yyyy", Locale.getDefault()).format(Date(v))
private fun typeName(t: String) = when (t) { CustodyTransactionType.RECEIVED_FROM_ORG -> "استلام من الجهة"; CustodyTransactionType.PAID_TO_PERSON -> "صرف للشخص"; CustodyTransactionType.RETURNED_FROM_PERSON -> "مرتجع من الشخص"; CustodyTransactionType.RETURNED_TO_ORG -> "مرتجع للجهة / تصفية"; else -> t }

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun CustodyDetailScreen2(vm: CustodyViewModel, custodyId: Long, onBack: () -> Unit, onOpenPerson: (Long) -> Unit) {
    val custody by vm.custody(custodyId).collectAsState(); val people by vm.persons(custodyId).collectAsState(); val accounts by vm.accounts(custodyId).collectAsState(); val tx by vm.transactions(custodyId).collectAsState(); val current = custody ?: return
    var currency by remember { mutableStateOf("YER") }; var operationType by remember { mutableStateOf(CustodyTransactionType.RECEIVED_FROM_ORG) }; var editing by remember { mutableStateOf<CustodyTransactionEntity?>(null) }; var deleting by remember { mutableStateOf<CustodyTransactionEntity?>(null) }; var editOwner by remember { mutableStateOf(false) }; var addPerson by remember { mutableStateOf(false) }; var more by remember { mutableStateOf(false) }
    Scaffold(topBar = { TopAppBar(title = { Text(current.name, fontWeight = FontWeight.Bold) }, navigationIcon = { IconButton(onClick = onBack) { Icon(Icons.AutoMirrored.Filled.ArrowBack, "رجوع") } }, actions = { IconButton(onClick = { editOwner = true }) { Icon(Icons.Default.Edit, "تعديل") }; IconButton(onClick = { more = true }) { Icon(Icons.Default.MoreVert, "المزيد") }; DropdownMenu(expanded = more, onDismissRequest = { more = false }) { DropdownMenuItem(text = { Text("أرشفة العهدة") }, onClick = { more = false; vm.archive(custodyId); onBack() }) } }) }) { pad ->
        LazyColumn(Modifier.fillMaxSize().padding(pad).padding(12.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
            item { Card(Modifier.fillMaxWidth()) { Column(Modifier.padding(14.dp)) { Text(current.name, fontWeight = FontWeight.Bold, style = MaterialTheme.typography.titleLarge); Text("الجهة: ${current.organizationName}"); if (current.phone.isNotBlank()) Text("الهاتف: ${current.phone}", style = MaterialTheme.typography.bodySmall); if (current.address.isNotBlank()) Text("العنوان: ${current.address}", style = MaterialTheme.typography.bodySmall) } } }
            item { CurrencyChips(currency) { currency = it } }
            item { Text("حسابات صاحب العهدة", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary); Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(6.dp)) { CURRENCIES.forEach { code -> val a = accounts.firstOrNull { it.holderType == "OWNER" && it.personId == null && it.currencyCode == code }; val b = tx.filter { it.accountId == a?.id && it.currencyCode == code }.sumOf { CustodyBalanceRules.ownerDelta(it.type, it.amountMinor) }; Card(Modifier.weight(1f)) { Column(Modifier.padding(7.dp), horizontalAlignment = Alignment.CenterHorizontally) { Text(code, fontWeight = FontWeight.Bold); Text(signed(b), color = when { b > 0 -> MaterialTheme.colorScheme.error; b < 0 -> MaterialTheme.colorScheme.secondary; else -> MaterialTheme.colorScheme.primary }, fontSize = 11.sp) } } } } }
            item { Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) { Button(onClick = { operationType = CustodyTransactionType.RECEIVED_FROM_ORG }, Modifier.weight(1f)) { Text("استلام من الجهة") }; OutlinedButton(onClick = { operationType = CustodyTransactionType.RETURNED_TO_ORG }, Modifier.weight(1f)) { Text("مرتجع للجهة / تصفية") } } }
            item { Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) { Text("الأشخاص", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary); TextButton(onClick = { addPerson = true }) { Text("إضافة شخص") } } }
            items(people, key = { it.id }) { person -> Card(Modifier.fillMaxWidth().clickable { onOpenPerson(person.id) }) { Column(Modifier.padding(11.dp)) { Text(person.name, fontWeight = FontWeight.Bold); Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(5.dp)) { CURRENCIES.forEach { code -> val b = tx.filter { it.personId == person.id && it.currencyCode == code }.sumOf { CustodyBalanceRules.personDelta(it.type, it.amountMinor) }; Text("$code ${signed(b)}", style = MaterialTheme.typography.bodySmall, color = when { b > 0 -> MaterialTheme.colorScheme.error; b < 0 -> MaterialTheme.colorScheme.secondary; else -> MaterialTheme.colorScheme.primary }) } } } } }
            item { Text("العمليات — $currency", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary) }
            items(tx.filter { it.currencyCode == currency }.sortedByDescending { it.transactionDate }, key = { it.id }) { t -> CustodyTransactionCard(t, vm, { editing = t }, { deleting = t }) }
        }
    }
    if (addPerson) CustodyPersonForm(current, people, { addPerson = false }) { p -> vm.addPerson(custodyId, p); addPerson = false }
    if (operationType.isNotBlank()) {
        var open by remember(custodyId, operationType) { mutableStateOf(operationType == CustodyTransactionType.RECEIVED_FROM_ORG) }
        if (open) CustodyOperationDialog(vm, custodyId, people, currency, operationType, null, { open = false }) { open = false; operationType = "" }
    }
    editing?.let { t -> CustodyOperationDialog(vm, custodyId, people, t.currencyCode, t.type, t, { editing = null }) { editing = null } }
    deleting?.let { t -> AlertDialog(onDismissRequest = { deleting = null }, title = { Text("حذف العملية نهائيًا") }, text = { Text("سيتم حذف العملية ومرفقاتها نهائيًا.") }, confirmButton = { TextButton(onClick = { vm.deleteTransaction(t.id); deleting = null }) { Text("حذف", color = MaterialTheme.colorScheme.error) } }, dismissButton = { TextButton(onClick = { deleting = null }) { Text("إلغاء") } }) }
    if (editOwner) CustodyEditDialog(current, { editOwner = false }) { vm.updateCustody(it); editOwner = false }
}

@Composable private fun CurrencyChips(selected: String, onSelect: (String) -> Unit) { Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()), horizontalArrangement = Arrangement.spacedBy(8.dp)) { CURRENCIES.forEach { FilterChip(selected == it, onClick = { onSelect(it) }, label = { Text(LABELS[it] ?: it) }) } } }

@Composable private fun CustodyTransactionCard(t: CustodyTransactionEntity, vm: CustodyViewModel, onEdit: () -> Unit, onDelete: () -> Unit) { var open by remember(t.id) { mutableStateOf(false) }; val attachments = remember(t.id) { vm.attachments(t.id) }; Card(Modifier.fillMaxWidth()) { Column(Modifier.padding(10.dp)) { Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) { Text(typeName(t.type), fontWeight = FontWeight.Bold); Text(SimpleDateFormat("dd-MM-yyyy HH:mm", Locale.getDefault()).format(Date(t.transactionDate)), style = MaterialTheme.typography.bodySmall) }; Text("${money(t.amountMinor)} ${t.currencyCode}", fontWeight = FontWeight.Bold, fontSize = 18.sp); if (t.description.isNotBlank()) Text(t.description, style = MaterialTheme.typography.bodySmall); Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) { if (attachments.isNotEmpty()) TextButton(onClick = { open = true }) { Text("المرفقات") }; IconButton(onClick = onEdit) { Icon(Icons.Default.Edit, "تعديل") }; IconButton(onClick = onDelete) { Icon(Icons.Default.Delete, "حذف نهائي") } } } }; if (open) CustodyAttachmentsDialog(attachments, { open = false }) { vm.deleteAttachment(it) } }

@OptIn(ExperimentalMaterial3Api::class)
@Composable fun CustodyPersonAccountScreen(vm: CustodyViewModel, custodyId: Long, personId: Long, onBack: () -> Unit) { val people by vm.persons(custodyId).collectAsState(); val tx by vm.transactions(custodyId).collectAsState(); val person = people.firstOrNull { it.id == personId } ?: return; var currency by remember { mutableStateOf("YER") }; var add by remember { mutableStateOf(false) }; var editing by remember { mutableStateOf<CustodyTransactionEntity?>(null) }; var deleting by remember { mutableStateOf<CustodyTransactionEntity?>(null) }; val rows = tx.filter { it.personId == personId && it.currencyCode == currency }.sortedByDescending { it.transactionDate }; val balance = rows.sumOf { CustodyBalanceRules.personDelta(it.type, it.amountMinor) }; Scaffold(topBar = { TopAppBar(title = { Text(person.name, fontWeight = FontWeight.Bold) }, navigationIcon = { IconButton(onClick = onBack) { Icon(Icons.AutoMirrored.Filled.ArrowBack, "رجوع") } }) }, floatingActionButton = { FloatingActionButton(onClick = { add = true }) { Text("+") } }) { pad -> LazyColumn(Modifier.fillMaxSize().padding(pad).padding(12.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) { item { Card(Modifier.fillMaxWidth()) { Column(Modifier.padding(14.dp)) { Text("الرصيد — $currency", fontWeight = FontWeight.Bold); Text(signed(balance), color = when { balance > 0 -> MaterialTheme.colorScheme.error; balance < 0 -> MaterialTheme.colorScheme.secondary; else -> MaterialTheme.colorScheme.primary }, fontSize = 21.sp, fontWeight = FontWeight.Bold) } } }; item { CurrencyChips(currency) { currency = it } }; items(rows, key = { it.id }) { t -> CustodyTransactionCard(t, vm, { editing = t }, { deleting = t }) } } }; if (add) CustodyOperationDialog(vm, custodyId, listOf(person), currency, CustodyTransactionType.PAID_TO_PERSON, null, { add = false }, personId) { add = false }; editing?.let { t -> CustodyOperationDialog(vm, custodyId, listOf(person), t.currencyCode, t.type, t, { editing = null }, personId) { editing = null } }; deleting?.let { t -> AlertDialog(onDismissRequest = { deleting = null }, title = { Text("حذف العملية نهائيًا") }, text = { Text("سيتم حذف العملية ومرفقاتها نهائيًا.") }, confirmButton = { TextButton(onClick = { vm.deleteTransaction(t.id); deleting = null }) { Text("حذف", color = MaterialTheme.colorScheme.error) } }, dismissButton = { TextButton(onClick = { deleting = null }) { Text("إلغاء") } }) } }

@Composable private fun CustodyOperationDialog(vm: CustodyViewModel, custodyId: Long, people: List<CustodyPersonEntity>, defaultCurrency: String, initialType: String, transaction: CustodyTransactionEntity?, onDismiss: () -> Unit, fixedPersonId: Long? = null, onFinished: () -> Unit) { val context = LocalContext.current; val keyboard = LocalSoftwareKeyboardController.current; val calc = LocalCalculatorController.current; var currency by remember(transaction?.id) { mutableStateOf(transaction?.currencyCode ?: defaultCurrency) }; var type by remember(transaction?.id) { mutableStateOf(transaction?.type ?: initialType) }; var personId by remember(transaction?.id) { mutableStateOf(transaction?.personId ?: fixedPersonId) }; var amount by remember(transaction?.id) { mutableStateOf(transaction?.let { money(it.amountMinor) } ?: "") }; var details by remember(transaction?.id) { mutableStateOf(transaction?.description ?: "") }; var date by remember(transaction?.id) { mutableStateOf(transaction?.transactionDate ?: System.currentTimeMillis()) }; var error by remember(transaction?.id) { mutableStateOf(false) }; var selected by remember(transaction?.id) { mutableStateOf<List<CustodyAttachmentStorage.Selected>>(emptyList()) }; var deleted by remember(transaction?.id) { mutableStateOf<List<CustodyTransactionAttachmentEntity>>(emptyList()) }; val existing = remember(transaction?.id) { transaction?.let { vm.attachments(it.id) }.orEmpty() }.filterNot { d -> deleted.any { it.id == d.id } }; val needsPerson = type == CustodyTransactionType.PAID_TO_PERSON || type == CustodyTransactionType.RETURNED_FROM_PERSON; DisposableEffect(calc, transaction?.id) { calc.setResultConsumer { amount = it; error = false }; onDispose { calc.setResultConsumer(null) } }
 Dialog(onDismissRequest = onDismiss, properties = DialogProperties(usePlatformDefaultWidth = false, decorFitsSystemWindows = false)) { Surface(Modifier.fillMaxWidth(.95f), shape = MaterialTheme.shapes.large, tonalElevation = 6.dp) { Column(Modifier.fillMaxWidth().verticalScroll(rememberScrollState()).imePadding().padding(16.dp), verticalArrangement = Arrangement.spacedBy(9.dp)) { Text(if (transaction == null) "إضافة عملية" else "تعديل العملية", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary); Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(7.dp)) { OutlinedTextField(amount, { amount = it; error = false }, Modifier.weight(1.3f), label = { Text("المبلغ") }, keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal), singleLine = true, isError = error, trailingIcon = { CalculatorButton(onClick = calc::open) }); OutlinedTextField(dateLabel(date), {}, Modifier.weight(1f), label = { Text("التاريخ") }, readOnly = true, singleLine = true, trailingIcon = { IconButton(onClick = { val d = Calendar.getInstance().apply { timeInMillis = date }; DatePickerDialog(context, { _, y, m, day -> d.set(y, m, day, 12, 0, 0); date = d.timeInMillis }, d.get(Calendar.YEAR), d.get(Calendar.MONTH), d.get(Calendar.DAY_OF_MONTH)).show() }) { Icon(Icons.Default.CalendarToday, "التاريخ") } }) }; if (error) Text("أدخل مبلغاً موجباً وبحد أقصى منزلتين عشريتين.", color = MaterialTheme.colorScheme.error, style = MaterialTheme.typography.bodySmall); OutlinedTextField(details, { details = it }, Modifier.fillMaxWidth(), label = { Text("التفاصيل") }, singleLine = true); Text("العملة", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary); CurrencyChips(currency) { currency = it }; Text("نوع العملية", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary); val kinds = if (fixedPersonId != null) listOf(CustodyTransactionType.PAID_TO_PERSON, CustodyTransactionType.RETURNED_FROM_PERSON) else listOf(CustodyTransactionType.RECEIVED_FROM_ORG, CustodyTransactionType.PAID_TO_PERSON, CustodyTransactionType.RETURNED_FROM_PERSON, CustodyTransactionType.RETURNED_TO_ORG); kinds.forEach { k -> Row(Modifier.fillMaxWidth().clickable { type = k; personId = if (k == CustodyTransactionType.RECEIVED_FROM_ORG || k == CustodyTransactionType.RETURNED_TO_ORG) null else (fixedPersonId ?: personId) }) { RadioButton(type == k, { type = k }); Text(typeName(k), Modifier.padding(top = 12.dp)) } }; if (needsPerson && fixedPersonId == null) { Text("الشخص", fontWeight = FontWeight.Bold, color = MaterialTheme.colorScheme.primary); people.forEach { p -> Row(Modifier.fillMaxWidth().clickable { personId = p.id }) { RadioButton(personId == p.id, { personId = p.id }); Text(p.name, Modifier.padding(top = 12.dp)) } } }; if (existing.isNotEmpty()) { Text("المرفقات الحالية", fontWeight = FontWeight.Bold); existing.forEach { a -> Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) { Text(a.fileName, Modifier.weight(1f), maxLines = 2); IconButton(onClick = { deleted = deleted + a }) { Icon(Icons.Default.Delete, "حذف المرفق") } } } }; val picker = selected.map { TransactionAttachmentStorage.Selected(it.uri, it.fileName, it.mimeType) }; TransactionAttachmentPicker(picker) { selected = it.map { CustodyAttachmentStorage.Selected(it.uri, it.fileName, it.mimeType) } }; Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) { Button(onClick = { val m = parseMinor(amount); if (m == null || m <= 0 || (needsPerson && personId == null)) { error = true; return@Button }; if (transaction == null) vm.addTransaction(custodyId, currency, type, personId, m, details, date, selected) else vm.updateTransaction(transaction.id, currency, type, personId, m, details, date, selected, deleted); keyboard?.hide(); onFinished() }, Modifier.weight(1f).semantics { contentDescription = "حفظ العملية" }) { Text("حفظ", fontWeight = FontWeight.Bold) }; OutlinedButton(onClick = { keyboard?.hide(); onDismiss() }, Modifier.weight(1f)) { Text("إلغاء") } } } } }
 if (calc.isOpen) Dialog(onDismissRequest = calc::close, properties = DialogProperties(usePlatformDefaultWidth = false, decorFitsSystemWindows = false)) { Card(Modifier.fillMaxWidth(.92f).imePadding()) { CalculatorOverlay(expression = calc.expression, result = calc.result.orEmpty(), onKey = calc::press, onClear = calc::clear, onBackspace = calc::backspace, onDismiss = calc::close, onUseResult = calc::useResult) } }
}

@Composable private fun CustodyAttachmentsDialog(items: List<CustodyTransactionAttachmentEntity>, onDismiss: () -> Unit, onDelete: (CustodyTransactionAttachmentEntity) -> Unit) { val context = LocalContext.current; AlertDialog(onDismissRequest = onDismiss, title = { Text("مرفقات العملية") }, text = { Column { items.forEach { a -> Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) { Text(a.fileName, Modifier.weight(1f), maxLines = 2); IconButton(onClick = { runCatching { val file = CustodyAttachmentStorage.fileFor(context, a); val uri = androidx.core.content.FileProvider.getUriForFile(context, "${context.packageName}.fileprovider", file); context.startActivity(Intent.createChooser(Intent(Intent.ACTION_VIEW).apply { setDataAndType(uri, a.mimeType); addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION) }, "فتح المرفق")) } }) { Icon(Icons.Default.OpenInNew, "فتح") }; IconButton(onClick = { onDelete(a) }) { Icon(Icons.Default.Delete, "حذف") } } } } }, confirmButton = { TextButton(onClick = onDismiss) { Text("إغلاق") } }) }

@Composable private fun CustodyPersonForm(c: CustodyEntity, existing: List<CustodyPersonEntity>, onDismiss: () -> Unit, onSave: (CustodyPersonEntity) -> Unit) { var name by remember { mutableStateOf("") }; var phone by remember { mutableStateOf("") }; var address by remember { mutableStateOf("") }; var notes by remember { mutableStateOf("") }; val matches = existing.filter { name.isNotBlank() && it.name.contains(name.trim(), true) }.take(5); AlertDialog(onDismissRequest = onDismiss, title = { Text("إضافة شخص") }, text = { Column(verticalArrangement = Arrangement.spacedBy(6.dp)) { OutlinedTextField(name, { name = it }, Modifier.fillMaxWidth(), label = { Text("الاسم") }, singleLine = true); matches.forEach { s -> TextButton(onClick = { name = s.name; phone = s.phone; address = s.address; notes = s.notes }, Modifier.fillMaxWidth()) { Text(s.name) } }; OutlinedTextField(phone, { phone = it }, Modifier.fillMaxWidth(), label = { Text("الهاتف") }, singleLine = true); OutlinedTextField(address, { address = it }, Modifier.fillMaxWidth(), label = { Text("العنوان") }, singleLine = true); OutlinedTextField(notes, { notes = it }, Modifier.fillMaxWidth(), label = { Text("الملاحظات") }, minLines = 2) } }, confirmButton = { Button(enabled = name.isNotBlank(), onClick = { onSave(CustodyPersonEntity(custodyId = c.id, name = name.trim(), phone = phone.trim(), address = address.trim(), notes = notes.trim())) }) { Text("حفظ") } }, dismissButton = { TextButton(onClick = onDismiss) { Text("إلغاء") } }) }

@Composable private fun CustodyEditDialog(c: CustodyEntity, onDismiss: () -> Unit, onSave: (CustodyEntity) -> Unit) { var name by remember { mutableStateOf(c.name) }; var phone by remember { mutableStateOf(c.phone) }; var address by remember { mutableStateOf(c.address) }; var notes by remember { mutableStateOf(c.notes) }; var org by remember { mutableStateOf(c.organizationName) }; var orgPhone by remember { mutableStateOf(c.organizationPhone) }; var orgAddress by remember { mutableStateOf(c.organizationAddress) }; var orgNotes by remember { mutableStateOf(c.organizationNotes) }; AlertDialog(onDismissRequest = onDismiss, title = { Text("تعديل بيانات العهدة") }, text = { Column(verticalArrangement = Arrangement.spacedBy(6.dp)) { OutlinedTextField(name,{name=it},Modifier.fillMaxWidth(),label={Text("اسم صاحب العهدة")},singleLine=true);OutlinedTextField(phone,{phone=it},Modifier.fillMaxWidth(),label={Text("الهاتف")},singleLine=true);OutlinedTextField(address,{address=it},Modifier.fillMaxWidth(),label={Text("العنوان")},singleLine=true);OutlinedTextField(notes,{notes=it},Modifier.fillMaxWidth(),label={Text("الملاحظات")},singleLine=true);Text("بيانات الجهة",fontWeight=FontWeight.Bold);OutlinedTextField(org,{org=it},Modifier.fillMaxWidth(),label={Text("اسم الجهة")},singleLine=true);OutlinedTextField(orgPhone,{orgPhone=it},Modifier.fillMaxWidth(),label={Text("هاتف الجهة")},singleLine=true);OutlinedTextField(orgAddress,{orgAddress=it},Modifier.fillMaxWidth(),label={Text("عنوان الجهة")},singleLine=true);OutlinedTextField(orgNotes,{orgNotes=it},Modifier.fillMaxWidth(),label={Text("ملاحظات الجهة")},singleLine=true) } }, confirmButton = { Button(enabled = name.isNotBlank() && org.isNotBlank(), onClick = { onSave(c.copy(name=name.trim(),phone=phone.trim(),address=address.trim(),notes=notes.trim(),organizationName=org.trim(),organizationPhone=orgPhone.trim(),organizationAddress=orgAddress.trim(),organizationNotes=orgNotes.trim())) }) { Text("حفظ") } }, dismissButton = { TextButton(onClick = onDismiss) { Text("إلغاء") } }) }
